//! Reads meshes written by the real Gmsh 4.15.2 (python wheel) in every
//! supported flavour: format 2.2 / 4.1 x ASCII / binary, for tetrahedral,
//! hexahedral and prismatic meshes of the box [0,2]x[0,1]x[0,1].
//! The files in `tests/data` were generated by `scripts/gen_gmsh_samples.py`.

use rcfd_io::gmsh;
use rcfd_mesh::quality::check_mesh;
use rcfd_mesh::PatchKind;
use std::path::Path;

fn data(name: &str) -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data").join(name)
}

#[test]
fn real_gmsh_files_all_variants() {
    // (kind, expected cell count)
    for (kind, cells) in [("tet", 1139usize), ("hex", 64), ("prism", 336)] {
        for ver in ["2.2", "4.1"] {
            let mut meshes = Vec::new();
            for fmt in ["ascii", "bin"] {
                let file = format!("{kind}_v{ver}_{fmt}.msh");
                let m = gmsh::read_file(data(&file)).unwrap_or_else(|e| panic!("{file}: {e}"));
                assert_eq!(m.n_cells(), cells, "{file}");
                assert!(
                    (m.total_volume() - 2.0).abs() < 1e-9,
                    "{file}: volume {}",
                    m.total_volume()
                );
                let mut names: Vec<&str> = m.patches().iter().map(|p| p.name.as_str()).collect();
                names.sort_unstable();
                assert_eq!(names, vec!["inlet", "outlet", "walls"], "{file}");
                assert_eq!(m.patch("inlet").unwrap().kind, PatchKind::Inlet);
                assert_eq!(m.patch("outlet").unwrap().kind, PatchKind::Outlet);
                assert_eq!(m.patch("walls").unwrap().kind, PatchKind::Wall);
                assert_eq!(m.cell_zone("fluid").unwrap().ids.len(), cells, "{file}");
                // boundary area of the box: 2*(2*1 + 2*1 + 1*1) = 10, split 1 / 1 / 8
                let area = |name: &str| m.patch(name).unwrap().faces().map(|f| m.face_area(f)).sum::<f64>();
                assert!((area("inlet") - 1.0).abs() < 1e-9, "{file}");
                assert!((area("outlet") - 1.0).abs() < 1e-9, "{file}");
                assert!((area("walls") - 8.0).abs() < 1e-9, "{file}");
                let q = check_mesh(&m);
                assert!(q.is_ok(), "{file}: {:?}", q.errors);
                meshes.push(m);
            }
            // ASCII and binary encodings of the same format version must give identical meshes
            // (2.2 and 4.1 order nodes/elements differently, so they are not compared with each other).
            let (a, b) = (meshes[0].topology(), meshes[1].topology());
            assert_eq!(
                (&a.face_points, &a.owner, &a.neighbour, &a.patches),
                (&b.face_points, &b.owner, &b.neighbour, &b.patches),
                "{kind} v{ver}"
            );
            // ASCII output is printed with limited digits, so coordinates agree only to rounding
            assert!(
                a.points
                    .iter()
                    .zip(&b.points)
                    .all(|(p, q)| (0..3).all(|d| (p[d] - q[d]).abs() < 1e-12)),
                "{kind} v{ver}"
            );
        }
    }
}
